const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Split the input into directive lines, keeping each line's 1-based number.
 *
 * @param {string} input the whole of standard input
 * @returns {{ number: number, words: string[] }[]}
 */
function directives(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const out = []
  for (let i = 0; i < lines.length; i += 1) {
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    out.push({ number: i + 1, words: text.split(/\s+/) })
  }
  return out
}

/**
 * Check a task name, reporting the offending line when it is malformed.
 *
 * @param {string} name the word to check
 * @param {number} line the 1-based line number it came from
 * @returns {string} the name itself
 */
function checkName(name, line) {
  if (!NAME.test(name)) throw new CliError(`error: line ${line}: invalid task name ${name}`)
  return name
}

/**
 * Read a build graph from the text of standard input.
 *
 * @param {string} input the whole of standard input
 * @returns {{ names: string[], cost: Map<string, number>, deps: Map<string, string[]> }}
 */
export function parseGraph(input) {
  /** @type {Map<string, number>} */
  const cost = new Map()
  /** @type {Map<string, Set<string>>} */
  const deps = new Map()
  /** @type {{ name: string, order: number }[]} */
  const used = []

  for (const { number, words } of directives(input)) {
    const directive = words[0]
    if (directive === 'task') {
      if (words.length !== 3) throw new CliError(`error: line ${number}: expected task <name> <cost>`)
      const name = checkName(words[1], number)
      if (!COST.test(words[2])) {
        throw new CliError(`error: line ${number}: cost must be a non-negative integer`)
      }
      if (cost.has(name)) throw new CliError(`error: line ${number}: task ${name} is declared twice`)
      cost.set(name, Number(words[2]))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${number}: expected dep <name> <dependency>...`)
      }
      for (let i = 1; i < words.length; i += 1) checkName(words[i], number)
      const name = words[1]
      used.push({ name, order: used.length })
      let set = deps.get(name)
      if (set === undefined) {
        set = new Set()
        deps.set(name, set)
      }
      for (let i = 2; i < words.length; i += 1) {
        used.push({ name: words[i], order: used.length })
        set.add(words[i])
      }
    } else {
      throw new CliError(`error: line ${number}: unknown directive ${directive}`)
    }
  }

  for (const { name } of used) {
    if (!cost.has(name)) throw new CliError(`error: unknown task ${name}`)
  }

  const names = [...cost.keys()].sort()
  /** @type {Map<string, string[]>} */
  const sorted = new Map()
  for (const name of names) sorted.set(name, [...(deps.get(name) ?? [])].sort())
  return { names, cost, deps: sorted }
}
"}

