{"file_path":"src/graph.js","content":"/**
 * @typedef {{ names: string[], cost: Map<string, number>, deps: Map<string, string[]> }} Graph
 */

/**
 * Find the first cycle a depth-first search meets, starting from each task in
 * ascending name order and walking each task's dependencies in the same order.
 *
 * @param {Graph} graph the parsed build graph
 * @returns {string[] | null} the cycle's names, the first repeated at the end
 */
export function findCycle(graph) {
  const state = new Map(graph.names.map((name) => [name, 0]))
  for (const root of graph.names) {
    if (state.get(root) !== 0) continue
    state.set(root, 1)
    const stack = [{ name: root, at: 0 }]
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = graph.deps.get(frame.name) ?? []
      if (frame.at < list.length) {
        const next = list[frame.at]
        frame.at += 1
        const seen = state.get(next)
        if (seen === 1) {
          const from = stack.findIndex((entry) => entry.name === next)
          return [...stack.slice(from).map((entry) => entry.name), next]
        }
        if (seen === 0) {
          state.set(next, 1)
          stack.push({ name: next, at: 0 })
        }
      } else {
        state.set(frame.name, 2)
        stack.pop()
      }
    }
  }
  return null
}

/**
 * Order the tasks so that every task follows all of its dependencies.
 *
 * @param {Graph} graph an acyclic build graph
 * @returns {string[]} the task names in a dependency-respecting order
 */
function topological(graph) {
  const waiting = new Map()
  const dependents = new Map(graph.names.map((name) => [name, []]))
  for (const name of graph.names) {
    const list = graph.deps.get(name) ?? []
    waiting.set(name, list.length)
    for (const dep of list) dependents.get(dep).push(name)
  }
  const queue = graph.names.filter((name) => waiting.get(name) === 0)
  const order = []
  for (let i = 0; i < queue.length; i += 1) {
    const name = queue[i]
    order.push(name)
    for (const next of dependents.get(name)) {
      const left = waiting.get(next) - 1
      waiting.set(next, left)
      if (left === 0) queue.push(next)
    }
  }
  return order
}

/**
 * Work out when each task runs with unlimited workers, how deep it sits and
 * how long the chain that begins at it is.
 *
 * @param {Graph} graph an acyclic build graph
 * @returns {{
 *   order: string[],
 *   start: Map<string, number>,
 *   finish: Map<string, number>,
 *   depth: Map<string, number>,
 *   priority: Map<string, number>,
 *   total: number,
 * }}
 */
export function analyse(graph) {
  const order = topological(graph)
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0
  for (const name of order) {
    let began = 0
    let level = 0
    for (const dep of graph.deps.get(name) ?? []) {
      began = Math.max(began, finish.get(dep))
      level = Math.max(level, depth.get(dep) + 1)
    }
    const ends = began + graph.cost.get(name)
    start.set(name, began)
    finish.set(name, ends)
    depth.set(name, level)
    total = Math.max(total, ends)
  }

  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    if (!priority.has(name)) priority.set(name, graph.cost.get(name))
  }
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    const own = priority.get(name)
    for (const dep of graph.deps.get(name) ?? []) {
      const through = graph.cost.get(dep) + own
      if (through > priority.get(dep)) priority.set(dep, through)
    }
  }

  return { order, start, finish, depth, priority, total }
}
"}

