{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { analyse, findCycle } from './graph.js'
import { pack } from './schedule.js'
import { explain, packed, waves } from './report.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

/**
 * Work out which report was asked for.
 *
 * @param {string[]} argv the arguments after the program name
 * @returns {{ mode: string, workers: number }}
 */
function readArguments(argv) {
  const mode = argv[0]
  if ((mode === 'waves' || mode === 'explain') && argv.length === 1) return { mode, workers: 0 }
  if (mode === 'pack' && argv.length === 2) {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new CliError('error: workers must be a positive integer')
    return { mode, workers: Number(argv[1]) }
  }
  throw new CliError(USAGE)
}

/** Read the whole of standard input, treating a closed stream as empty. */
function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/**
 * Produce the report for one run.
 *
 * @param {string[]} argv the arguments after the program name
 * @returns {string} the whole of standard output
 */
function main(argv) {
  const { mode, workers } = readArguments(argv)
  const graph = parseGraph(readInput())
  const cycle = findCycle(graph)
  if (cycle !== null) throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  const analysis = analyse(graph)
  if (mode === 'waves') return waves(graph, analysis)
  if (mode === 'explain') return explain(graph, analysis)
  return packed(pack(graph, analysis.priority, workers))
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (error) {
  if (!(error instanceof CliError)) throw error
  process.stderr.write(`${error.message}\n`)
  process.exit(error.code)
}
"}

